import Foundation

extension DigitalGuides {
    static let digitalIdentity = DirectoryGuide(
        cardSummary: .init(ukrainian: "Отримання ID Austria, цифрові посвідчення й відновлення", german: "ID Austria, digitale Nachweise und Wiederherstellung"),
        introduction: .init(ukrainian: "ID Austria — безплатний засіб входу й підпису. Для іноземних громадян важливі зв’язок з Австрією, правильне місце реєстрації та строк дії.", german: "ID Austria ist ein kostenloser Zugang und eine Signatur. Für ausländische Staatsangehörige sind Inlandsbezug, richtige Registrierungsstelle und Gültigkeitsdauer wichtig."),
        sections: [
            .init("eligibility", "person.crop.circle.badge.checkmark", "Хто може зареєструватися", "Wer sich registrieren kann", "Громадяни України та інших держав після 14 років можуть отримати ID Austria за достатнього зв’язку з Австрією — наприклад, проживання, навчання або робота. Реєстрацію іноземців проводять Landespolizeidirektion чи відділення Finanzamt Österreich; не кожна громада реєструє іноземців. Перед записом уточніть прийом саме для іноземних громадян.", "Ukrainische und andere ausländische Staatsangehörige können ab 14 Jahren mit ausreichendem Inlandsbezug ID Austria erhalten, etwa durch Wohnsitz, Studium oder Arbeit. Registrieren können sie bei Landespolizeidirektion oder Dienststellen des Finanzamts Österreich; nicht jede Gemeinde registriert Ausländer. Vor Termin ausdrücklich die Zuständigkeit für ausländische Staatsangehörige prüfen.", source: registration),
            .init("appointment", "person.text.rectangle", "Підготуйтеся до прийому", "Termin vorbereiten", "Візьміть чинний паспорт або ID-картку, підтвердження зв’язку з Австрією (наприклад, Meldebestätigung, студентський квиток або довідку роботодавця) і, якщо потрібно, актуальне фото не старше шести місяців. Установіть офіційний застосунок ID Austria й візьміть смартфон. Після перевірки особи завершіть налаштування логіна, пароля для підпису та другого фактора за інструкцією установи; збережіть виданий папір із кодами в безпечному місці.", "Gültigen Reisepass oder Personalausweis, Nachweis des Inlandsbezugs (etwa Meldebestätigung, Studierendenausweis oder Arbeitgeberbestätigung) und gegebenenfalls ein höchstens sechs Monate altes Passfoto mitbringen. Offizielle App ID Austria installieren und Smartphone mitnehmen. Nach Identitätsprüfung Benutzername, Signatur-Passwort und zweiten Faktor nach Behördenanleitung fertigstellen; ausgehändigtes Blatt mit Codes sicher verwahren.", source: registration),
            .init("app", "iphone.gen3", "Застосунок і сайт мають різні ролі", "App und Website unterscheiden", "Застосунок «ID Austria» замінив «Digitales Amt» і насамперед підтверджує вхід та електронний підпис. Самі державні послуги шукайте на oesterreich.gv.at або на сайті відповідальної установи. Коли з’являється запит на підпис, звірте назву послуги та документ із дією, яку ви щойно почали; невідомий запит відхиліть.", "Die App „ID Austria“ hat „Digitales Amt“ abgelöst und dient vor allem der Anmeldung und elektronischen Signatur. Die eigentlichen Amtsservices finden Sie auf oesterreich.gv.at oder bei der zuständigen Behörde. Bei einer Signaturanfrage Dienst und Dokument mit Ihrer gerade begonnenen Handlung abgleichen; unbekannte Anfragen ablehnen.", source: app),
            .init("validity", "calendar", "Перевіряйте строк чинності", "Gültigkeit prüfen", "Для іноземних громадян ID Austria зазвичай дійсна три роки, за наявності головного місця проживання в Австрії — п’ять. На відміну від громадян Австрії, її не можна просто подовжити онлайн: після закінчення потрібна нова реєстрація в уповноваженій установі. Перевірте конкретну дату у своєму профілі завчасно, особливо перед строковою заявою.", "Für ausländische Staatsangehörige gilt ID Austria grundsätzlich drei Jahre, bei Hauptwohnsitz in Österreich fünf Jahre. Anders als bei österreichischen Staatsangehörigen ist keine einfache Onlineverlängerung möglich; danach ist eine neue Registrierung bei der zuständigen Behörde nötig. Konkretes Ablaufdatum rechtzeitig im eigenen Konto prüfen, besonders vor einem fristgebundenen Antrag.", source: registration),
            .init("new-device", "arrow.triangle.2.circlepath", "Новий телефон або номер", "Neues Telefon oder neue Nummer", "Поки старий пристрій працює, перевірте в «ID Austria verwalten» прив’язаний номер і додайте доступний спосіб підтвердження. Для нового телефона потрібен доступ до зареєстрованого номера, щоб отримати SMS, або інший чинний фактор, наприклад FIDO-ключ. Дотримуйтесь офіційної інструкції для нового телефона; без номера й іншого фактора доведеться зареєструвати ID Austria заново.", "Solange das alte Gerät funktioniert, hinterlegte Nummer in „ID Austria verwalten“ prüfen und einen verfügbaren weiteren Faktor vorbereiten. Für ein neues Smartphone brauchen Sie Zugriff auf die registrierte Nummer für SMS oder einen anderen aktiven Faktor wie FIDO-Schlüssel. Offizielle Anleitung zum Gerätewechsel nutzen; ohne Nummer und weiteren Faktor ist eine Neuregistrierung nötig.", source: newPhone),
            .init("lost", "iphone.slash", "Телефон втрачено або викрадено", "Telefon verloren oder gestohlen", "Негайно захистіть SIM у мобільного оператора. Якщо ще маєте інший чинний спосіб входу, від’єднайте втрачений пристрій у «ID Austria verwalten» і прив’яжіть новий. Якщо є ризик чужого доступу, зателефонуйте до служби відкликання ID Austria: +43 1 715 20 60; повне відкликання означає, що потім знадобиться нова реєстрація. Офіційні контакти й варіанти підтримки наведені за посиланням.", "SIM umgehend beim Mobilfunkanbieter sichern. Besteht noch ein anderer Anmeldefaktor, verlorenes Gerät in „ID Austria verwalten“ abmelden und neues verknüpfen. Bei Gefahr fremden Zugriffs den amtlichen Widerrufsdienst unter +43 1 715 20 60 anrufen; vollständiger Widerruf erfordert danach eine neue Registrierung. Amtliche Kontakte und Hilfewege stehen im Link.", source: identityContact),
            .init("cards", "person.text.rectangle", "ID Austria — не кожен цифровий документ", "ID Austria ist nicht jeder digitale Ausweis", "Для показу цифрового посвідчення існує окремий застосунок «eAusweise». Доступність конкретного документа залежить від повної функції ID Austria та наявності даних в австрійському реєстрі: наприклад, цифрові права потребують австрійського пластикового посвідчення. Не вважайте, що український паспорт чи права автоматично з’являться в eAusweise; перевірте умови потрібного документа перед поїздкою.", "Für digitale Nachweise gibt es die eigene App „eAusweise“. Ob ein bestimmter Ausweis verfügbar ist, hängt von voller ID-Austria-Funktion und Daten im österreichischen Register ab: Der digitale Führerschein setzt etwa einen österreichischen Scheckkartenführerschein voraus. Ukrainischer Pass oder Führerschein erscheinen nicht automatisch in eAusweise; Voraussetzungen des benötigten Nachweises vor Reise prüfen.", source: digitalCards)
        ], sources: [registration, app, identityManagement, newPhone, identityContact, digitalCards]
    )
}
